module.exports = function merge(dest, src, redefine) {
  if (redefine === undefined) redefine = true;
  Object.getOwnPropertyNames(src).forEach(function (name) {
    if (!redefine && Object.prototype.hasOwnProperty.call(dest, name)) return;
    Object.defineProperty(dest, name, Object.getOwnPropertyDescriptor(src, name));
  });
  return dest;
};
